I'll create a comprehensive calculator with Python. Here are several versions from basic to advanced:

## Version 1: Simple Calculator

```python
def simple_calculator():
    print("=== Simple Calculator ===")
    print("Operations: +, -, *, /")

    try:
        num1 = float(input("Enter first number: "))
        operator = input("Enter operator (+, -, *, /): ")
        num2 = float(input("Enter second number: "))

        if operator == '+':
            result = num1 + num2
        elif operator == '-':
            result = num1 - num2
        elif operator == '*':
            result = num1 * num2
        elif operator == '/':
            if num2 != 0:
                result = num1 / num2
            else:
                return "Error: Division by zero!"
        else:
            return "Error: Invalid operator!"

        return f"{num1} {operator} {num2} = {result}"

    except ValueError:
        return "Error: Please enter valid numbers!"

# Run simple calculator
print(simple_calculator())
```

## Version 2: Advanced Calculator Class

```python
import math

class Calculator:
    def __init__(self):
        self.history = []

    def add(self, a, b):
        result = a + b
        self.history.append(f"{a} + {b} = {result}")
        return result

    def subtract(self, a, b):
        result = a - b
        self.history.append(f"{a} - {b} = {result}")
        return result

    def multiply(self, a, b):
        result = a * b
        self.history.append(f"{a} * {b} = {result}")
        return result

    def divide(self, a, b):
        if b == 0:
            raise ValueError("Cannot divide by zero!")
        result = a / b
        self.history.append(f"{a} / {b} = {result}")
        return result

    def power(self, base, exponent):
        result = base ** exponent
        self.history.append(f"{base} ^ {exponent} = {result}")
        return result

    def square_root(self, number):
        if number < 0:
            raise ValueError("Cannot calculate square root of negative number!")
        result = math.sqrt(number)
        self.history.append(f"√{number} = {result}")
        return result

    def percentage(self, number, percent):
        result = (number * percent) / 100
        self.history.append(f"{percent}% of {number} = {result}")
        return result

    def factorial(self, n):
        if n < 0:
            raise ValueError("Factorial is not defined for negative numbers!")
        if n > 170:
            raise ValueError("Number too large for factorial calculation!")
        result = math.factorial(int(n))
        self.history.append(f"{n}! = {result}")
        return result

    def sin(self, angle_degrees):
        angle_radians = math.radians(angle_degrees)
        result = math.sin(angle_radians)
        self.history.append(f"sin({angle_degrees}°) = {result}")
        return result

    def cos(self, angle_degrees):
        angle_radians = math.radians(angle_degrees)
        result = math.cos(angle_radians)
        self.history.append(f"cos({angle_degrees}°) = {result}")
        return result

    def tan(self, angle_degrees):
        angle_radians = math.radians(angle_degrees)
        result = math.tan(angle_radians)
        self.history.append(f"tan({angle_degrees}°) = {result}")
        return result

    def logarithm(self, number, base=10):
        if number <= 0:
            raise ValueError("Logarithm is not defined for non-positive numbers!")
        if base == 10:
            result = math.log10(number)
            self.history.append(f"log₁₀({number}) = {result}")
        elif base == math.e:
            result = math.log(number)
            self.history.append(f"ln({number}) = {result}")
        else:
            result = math.log(number, base)
            self.history.append(f"log_{base}({number}) = {result}")
        return result

    def clear_history(self):
        self.history.clear()
        print("History cleared!")

    def show_history(self):
        if not self.history:
            print("No calculations in history.")
        else:
            print("\n=== Calculation History ===")
            for i, calc in enumerate(self.history, 1):
                print(f"{i}. {calc}")
```

## Version 3: Interactive Calculator with Menu

```python
def interactive_calculator():
    calc = Calculator()

    print("\n🧮 Advanced Calculator")
    print("=" * 50)

    while True:
        print("\nSelect an operation:")
        print("1.  Addition (+)")
        print("2.  Subtraction (-)")
        print("3.  Multiplication (×)")
        print("4.  Division (÷)")
        print("5.  Power (^)")
        print("6.  Square Root (√)")
        print("7.  Percentage (%)")
        print("8.  Factorial (!)")
        print("9.  Sine (sin)")
        print("10. Cosine (cos)")
        print("11. Tangent (tan)")
        print("12. Logarithm (log)")
        print("13. Natural Log (ln)")
        print("14. Show History")
        print("15. Clear History")
        print("16. Exit")

        try:
            choice = input("\nEnter choice (1-16): ").strip()

            if choice == '16':
                print("Thank you for using the calculator! 👋")
                break

            elif choice == '14':
                calc.show_history()
                continue

            elif choice == '15':
                calc.clear_history()
                continue

            elif choice in ['1', '2', '3', '4', '5', '7']:
                num1 = float(input("Enter first number: "))
                num2 = float(input("Enter second number: "))

                if choice == '1':
                    result = calc.add(num1, num2)
                elif choice == '2':
                    result = calc.subtract(num1, num2)
                elif choice == '3':
                    result = calc.multiply(num1, num2)
                elif choice == '4':
                    result = calc.divide(num1, num2)
                elif choice == '5':
                    result = calc.power(num1, num2)
                elif choice == '7':
                    result = calc.percentage(num1, num2)

                print(f"Result: {result}")

            elif choice in ['6', '8']:
                num = float(input("Enter number: "))

                if choice == '6':
                    result = calc.square_root(num)
                elif choice == '8':
                    result = calc.factorial(num)

                print(f"Result: {result}")

            elif choice in ['9', '10', '11']:
                angle = float(input("Enter angle in degrees: "))

                if choice == '9':
                    result = calc.sin(angle)
                elif choice == '10':
                    result = calc.cos(angle)
                elif choice == '11':
                    result = calc.tan(angle)

                print(f"Result: {result:.6f}")

            elif choice in ['12', '13']:
                num = float(input("Enter number: "))

                if choice == '12':
                    base = input("Enter base (press Enter for base 10): ").strip()
                    if base == '':
                        result = calc.logarithm(num)
                    else:
                        result = calc.logarithm(num, float(base))
                elif choice == '13':
                    result = calc.logarithm(num, math.e)

                print(f"Result: {result}")

            else:
                print("Invalid choice! Please select 1-16.")

        except ValueError as e:
            print(f"Error: {e}")
        except Exception as e:
            print(f"An error occurred: {e}")

        input("\nPress Enter to continue...")

# Run the interactive calculator
if __name__ == "__main__":
    interactive_calculator()
```

## Version 4: Expression Evaluator Calculator

```python
import re

class ExpressionCalculator:
    def __init__(self):
        self.variables = {}

    def evaluate_expression(self, expression):
        """Safely evaluate mathematical expressions"""
        try:
            # Remove spaces
            expression = expression.replace(' ', '')

            # Replace common mathematical functions
            expression = expression.replace('sqrt(', 'math.sqrt(')
            expression = expression.replace('sin(', 'math.sin(')
            expression = expression.replace('cos(', 'math.cos(')
            expression = expression.replace('tan(', 'math.tan(')
            expression = expression.replace('log(', 'math.log10(')
            expression = expression.replace('ln(', 'math.log(')
            expression = expression.replace('pi', 'math.pi')
            expression = expression.replace('e', 'math.e')
            expression = expression.replace('^', '**')

            # Safe evaluation
            allowed_names = {
                k: v for k, v in math.__dict__.items() if not k.startswith("__")
            }
            allowed_names.update({"abs": abs, "round": round})

            result = eval(expression, {"__builtins__": {}}, allowed_names)
            return result

        except Exception as e:
            raise ValueError(f"Invalid expression: {e}")

    def set_variable(self, name, value):
        """Store a variable for later use"""
        self.variables[name] = value
        print(f"Variable '{name}' set to {value}")

    def get_variable(self, name):
        """Get a stored variable"""
        return self.variables.get(name, None)

    def list_variables(self):
        """List all stored variables"""
        if not self.variables:
            print("No variables stored.")
        else:
            print("\nStored Variables:")
            for name, value in self.variables.items():
                print(f"  {name} = {value}")

def expression_calculator():
    calc = ExpressionCalculator()

    print("\n📊 Expression Calculator")
    print("=" * 50)
    print("Enter mathematical expressions like: 2+3*4, sqrt(16), sin(30), etc.")
    print("Commands: 'vars' (list variables), 'exit' (quit)")
    print("Set variables: x = 5")

    while True:
        try:
            user_input = input("\n>>> ").strip()

            if user_input.lower() == 'exit':
                print("Goodbye! 👋")
                break

            elif user_input.lower() == 'vars':
                calc.list_variables()
                continue

            elif '=' in user_input and not any(op in user_input.split('=')[0] for op in ['!', '<', '>', '==']):
                # Variable assignment
                parts = user_input.split('=')
                if len(parts) == 2:
                    var_name = parts[0].strip()
                    var_value = calc.evaluate_expression(parts[1].strip())
                    calc.set_variable(var_name, var_value)
                continue

            else:
                # Replace variables in expression
                expression = user_input
                for var_name, var_value in calc.variables.items():
                    expression = expression.replace(var_name, str(var_value))

                result = calc.evaluate_expression(expression)
                print(f"Result: {result}")

        except Exception as e:
            print(f"Error: {e}")

# Run the expression calculator
if __name__ == "__main__":
    expression_calculator()
```

